### Fungsi sebagai props

```jsx
function DaftarProduk({ onBeli }) {
  return <button onClick={() => onBeli('Kopi Susu')}>Beli Kopi</button>;
}

function IkonKeranjang({ jumlah }) {
  return <span>🛒 {jumlah}</span>;
}

export default function App() {
  const [keranjang, setKeranjang] = useState([]);

  function handleBeli(nama) {
    setKeranjang([...keranjang, nama]);
  }

  return (
    <>
      <IkonKeranjang jumlah={keranjang.length} />
      <DaftarProduk onBeli={handleBeli} />
    </>
  );
}
```

Alurnya:
1. Tombol di `DaftarProduk` diklik, memanggil `onBeli('Kopi Susu')`.
2. `onBeli` adalah `handleBeli` milik `App`, yang mengubah state.
3. `App` digambar ulang, dan `IkonKeranjang` menerima `jumlah` yang baru.

Data mengalir **ke bawah** lewat props, sedangkan kejadian mengalir **ke atas** lewat fungsi.

### Contoh

Sari memisahkan daftar dan ringkasan keranjang:

```jsx
import { useState } from 'react';

const produk = [
  { id: 1, nama: 'Kopi Susu', harga: 15000 },
  { id: 2, nama: 'Teh Melati', harga: 8000 },
];

function DaftarProduk({ onBeli }) {
  return (
    <div>
      {produk.map((p) => (
        <button key={p.id} onClick={() => onBeli(p)}>Beli {p.nama}</button>
      ))}
    </div>
  );
}

function Ringkasan({ isi }) {
  const total = isi.reduce((jml, p) => jml + p.harga, 0);
  return <p>🛒 {isi.length} barang, total Rp{total.toLocaleString('id-ID')}</p>;
}

export default function App() {
  const [keranjang, setKeranjang] = useState([]);
  return (
    <div>
      <Ringkasan isi={keranjang} />
      <DaftarProduk onBeli={(p) => setKeranjang([...keranjang, p])} />
    </div>
  );
}
```

Setiap klik "Beli" mengubah state di `App`, dan `Ringkasan` langsung ikut berubah.

